import{c as l,Q as a,j as e,m as s}from"./chunks/framework.DOi4mjdC.js";const i="/assets/zh-cn_image_0000002354202658.CEoOhmbL.png",n="/assets/zh-cn_image_0000002355276604.B1Y2Q1xB.png",o="/assets/zh-cn_image_0000002447772589.D_yUa99k.png",u="/assets/zh-cn_image_0000002388916821.Ce0k3Xtp.png",q=JSON.parse('{"title":"Matmul高阶API使能NBuffer33模板","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能NBuffer33模板","slug":"matmul高阶api使能nbuffer33模板"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能NBuffer33模板.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能NBuffer33模板.md"}'),p={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能NBuffer33模板.md"};function r(g,t,c,d,m,f){return a(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="matmul高阶api使能nbuffer33模板" tabindex="-1">Matmul高阶API使能NBuffer33模板 <a class="header-anchor" href="#matmul高阶api使能nbuffer33模板" aria-label="Permalink to &quot;Matmul高阶API使能NBuffer33模板&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在矩阵乘算子场景中，使用Matmul高阶API进行矩阵乘法计算，使能NBuffer33模板对算子性能的提升效果**。**NBuffer33模板的实现为单核计算的A矩阵切分为3x3个基本块，该3x3个A矩阵的基本块全载和保持在L1 Buffer中，每次与3x1个B矩阵的基本块计算矩阵乘，同时DoubleBuffer并行搬入下次计算所需的3x1个B矩阵基本块，直到singleCoreN方向的矩阵乘计算完成。针对MTE2 Bound场景，通过NBuffer33算法的切分数据方式，错开搬运流水，减少单次搬运的数据量，平衡MTE2和FixPipe的数据流量，让两者带宽均匀分布。NBuffer33模板的详细介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulPolicy.md" target="_blank" rel="noreferrer">MatmulPolicy</a>。</p><ul><li><p>使能NBuffer33模板的适用场景</p><p>MTE2 Bound的场景，Tiling参数满足约束条件时，可以使能NBuffer33模板。</p></li><li><p>使能NBuffer33模板的约束条件</p><ul><li>仅支持MatmulConfig为MDL模板。</li><li>A矩阵、B矩阵的内存逻辑位置只支持TPosition::GM。</li><li>仅支持纯Cube模式（只有矩阵计算），暂不支持MIX模式（包含矩阵计算和矢量计算）。</li><li>仅支持通过IterateAll接口获取Matmul的计算结果C矩阵。</li><li>stepM、stepKa、stepKb小于等于3，且满足：stepKa=stepKb=Ceil(singleCoreK/baseK)。</li><li>A矩阵全载的基本块大小与B矩阵载入的基本块大小之和不超过L1 Buffer的大小。</li></ul></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;256, 192&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;192, 512&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共24个核，算子中使能高阶API Matmul的纯Cube模式，使用MDL模板，Tiling参数如下：</p><ul><li>原始shape：M=256, N=512, K=192。</li><li>单核shape：singleCoreM=256，singleCoreN=256，singleCoreK=192。</li><li>基本块shape：baseM=128，baseN=256，baseK=64。</li><li>L1缓存相关Tiling参数：stepM=2，stepN=1，stepKa=3，stepKb=3。</li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据，重点分析Cube、Fixpipe的流水情况。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li><p>优化前的流水图如下，MatmulPolicy的默认模板下A、B矩阵全载，A、B矩阵都只搬运一次。此时MTE2执行时间较长，且流水整体呈串行。</p><p><img src="'+i+'" alt=""></p></li><li><p>优化前的Profiling数据如下，aic_time平均耗时34.01us。<img src="'+n+`" alt=""></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>使能NBuffer33模板：在GetTiling接口前，调用SetMatmulConfigParams接口开启NBuffer33模式，使获取的Tiling满足要求；Kernel侧在创建Matmul对象时使能NBuffer33模板。使能NBuffer33模板的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_nbuffer33" target="_blank" rel="noreferrer">使能NBuffer33模板策略的样例</a>。具体步骤如下：</p><ul><li><p>Tiling实现</p><p>调用GetTiling接口获取TCubeTiling结构体前，开启NBuffer33模式。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>matmul_tiling::MatmulConfigParams matmulConfigParams(1, false,</span></span>
<span class="line"><span>    matmul_tiling::ScheduleType::N_BUFFER_33, /* NBuffer33模式 */</span></span>
<span class="line"><span>    matmul_tiling::MatrixTraverse::NOSET, false);</span></span>
<span class="line"><span>cubeTiling.SetMatmulConfigParams(matmulConfigParams);</span></span>
<span class="line"><span>if (cubeTiling.GetTiling(tilingData) == -1) {</span></span>
<span class="line"><span>    std::cout &lt;&lt; &quot;Generate tiling failed.&quot; &lt;&lt; std::endl;</span></span>
<span class="line"><span>    return {};</span></span>
<span class="line"><span>}</span></span></code></pre></div></li><li><p>Kernel实现</p><p>设置模板参数MatmulPolicy为NBuffer33模板策略，创建Matmul对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::MatmulImpl&lt;</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, aType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, bType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, cType&gt;,</span></span>
<span class="line"><span>    AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, biasType&gt;, CFG_MDL,</span></span>
<span class="line"><span>    AscendC::MatmulCallBackFunc&lt;nullptr, nullptr, nullptr&gt;,</span></span>
<span class="line"><span>    AscendC::Impl::Detail::NBuffer33MatmulPolicy&gt; matmulObj;</span></span></code></pre></div></li></ul><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>优化后的流水图如下，Tiling参数不变，但由于stepM为2，NBuffer33模式会将左矩阵数据的搬运拆分为两次。可以看到，第一次MTE2结束后的计算过程（包括MTE1、MMAD和FIXPIPE）可以和第二次MTE2并行。分块搬运数据可以减少一次搬运数据导致的部分头开销，优化加载数据的性能。</p><p><img src="`+o+'" alt=""></p></li><li><p>优化后的Profiling数据如下，aic_time平均耗时32.66us，较优化前的34.01us有所提升。<img src="'+u+'" alt=""></p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>MTE2 Bound的场景，Tiling参数满足stepM、stepKa、stepKb小于等于3的条件时，可以考虑使能NBuffer33模板，切分矩阵将搬运流水错开， 减少单次搬运的数据量，平衡MTE2和FixPipe的数据流量。</p>',20)])])}const b=l(p,[["render",r]]);export{q as __pageData,b as default};
